import{_ as s,o as t,c as a,a3 as i}from"./chunks/framework.CVt6dz2a.js";const k=JSON.parse('{"title":"EP.18 把场景拆成乐高积木","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.18-r3f-components.md","filePath":"comics/EP.18-r3f-components.md","lastUpdated":1793881879000}'),o={name:"comics/EP.18-r3f-components.md"};function l(n,e,r,h,d,c){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="ep-18-把场景拆成乐高积木" tabindex="-1">EP.18 把场景拆成乐高积木 <a class="header-anchor" href="#ep-18-把场景拆成乐高积木" aria-label="Permalink to &quot;EP.18 把场景拆成乐高积木&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/18-react-three-fiber/basics">18.1 基础入门：声明式 3D 与第一个 R3F 场景</a> 延伸阅读：<a href="./../guide/18-react-three-fiber/advanced">进阶篇</a> · <a href="./../guide/18-react-three-fiber/practice">实战篇</a> 动手演示：本模块为 React 技术栈，演示以 StackBlitz 外链呈现（见 <a href="./../guide/18-react-three-fiber/basics#运行效果展示">18.1 运行效果展示</a>）；本地占位页：<a href="./../public/demos/r3f/placeholder.html">r3f placeholder</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>像素酱的原生 three 项目一个文件揉了 800 行：场景、灯光、模型、动画全在一起，产品一句&quot;换个颜色&quot;就得翻半天。</td></tr><tr><td>② 揭秘</td><td>码叔点破命令式 vs 声明式：命令式一步步指挥&quot;怎么做&quot;，声明式只描述&quot;要什么&quot;——JSX 嵌套就是 scene.add，React 负责比对更新。</td></tr><tr><td>③ 实证</td><td>场景拆成 <code>&lt;Lights/&gt;</code>、<code>&lt;Model/&gt;</code>、<code>&lt;Effects/&gt;</code> 三块积木后，需求变更只改一行 props，800 行大文件瘦身成十几个小组件。</td></tr><tr><td>④ 结案</td><td>坑点清单：args 传构造参数、useFrame 里别 setState、高频状态走 transient 读取；码叔总结&quot;把怎么做交给渲染器&quot;。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-命令式代码的失控临界点" tabindex="-1">① 命令式代码的失控临界点 <a class="header-anchor" href="#_1-命令式代码的失控临界点" aria-label="Permalink to &quot;① 命令式代码的失控临界点&quot;">​</a></h3><p>原生 three 的写法是&quot;一步步指挥&quot;：new 对象、设属性、add 进场景、在循环里手动驱动。小场景很直观，但对象一多，<strong>创建、布局、动画、事件</strong>四类逻辑全部揉在同一个文件里——改一处要先读懂八百行。问题不在 three，在于组织方式：没有任何机制帮你把&quot;灯光&quot;&quot;模型&quot;&quot;特效&quot;分开。</p><h3 id="_2-声明式-只描述-要什么" tabindex="-1">② 声明式：只描述&quot;要什么&quot; <a class="header-anchor" href="#_2-声明式-只描述-要什么" aria-label="Permalink to &quot;② 声明式：只描述&quot;要什么&quot;&quot;">​</a></h3><p>R3F 把 three 的每个类映射成一个小写驼峰标签，JSX 的结构就是场景图的结构：</p><div class="language-jsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 命令式：亲自指挥每一步</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> THREE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Mesh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(geo, mat)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scene.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(m)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 声明式：写出&quot;场景里有个 mesh&quot;即可</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">mesh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">boxGeometry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">mesh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>React 的 reconciler 负责比对前后 JSX 的差异并调用底层 three API：标签消失就 remove、属性变了就重新赋值。你从&quot;指挥者&quot;变成&quot;描述者&quot;。映射四条规则：驼峰标签 = three 类、属性 = 实例赋值、<code>args</code> = 构造参数、<code>attach</code> = 挂载到父对象的命名属性。</p><h3 id="_3-组件化-乐高积木" tabindex="-1">③ 组件化 = 乐高积木 <a class="header-anchor" href="#_3-组件化-乐高积木" aria-label="Permalink to &quot;③ 组件化 = 乐高积木&quot;">​</a></h3><p>声明式的真正红利是<strong>组件复用</strong>。把灯光、模型、特效各自封装成组件后：</p><div class="language-jsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Canvas</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> shadows</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Lights</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt; &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Model</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> url</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{url} /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Effects</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bloom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Canvas</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>需求变更不再是&quot;翻 800 行找那一行&quot;，而是改一行 props：换模型改 <code>url</code>、关特效删掉 <code>&lt;Effects /&gt;</code>。组件还能跨项目搬运——这正是 18.3 实战篇封装 <code>&lt;SceneCanvas /&gt;</code> 与 <code>&lt;ProductViewer /&gt;</code> 的动机。</p><h3 id="_4-三条高频坑点" tabindex="-1">④ 三条高频坑点 <a class="header-anchor" href="#_4-三条高频坑点" aria-label="Permalink to &quot;④ 三条高频坑点&quot;">​</a></h3><ol><li><strong><code>args</code> 传构造参数</strong>：<code>&lt;boxGeometry args={[1,1,1]} /&gt;</code> 等价于 <code>new THREE.BoxGeometry(1,1,1)</code>；写错位置（写成 props）构造参数拿不到。</li><li><strong>useFrame 里别 setState</strong>：每帧 setState = React 每秒重渲染 60 次，帧率崩塌；高频动画一律 <code>ref.current</code> 直改 three 对象。</li><li><strong>高频状态走 transient 读取</strong>：转速这类&quot;每帧要读但不进 JSX&quot;的值存 zustand，在 useFrame 里 <code>getState()</code> 直读，不订阅、不触发渲染。</li></ol><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：构造函数的参数在 JSX 里怎么传？</strong> 用 <code>args</code> 数组：<code>args={[1, 1, 1]}</code> 按位对应构造参数；无参构造可省略。</li><li><strong>Q：useFrame 里能 setState 吗？</strong> 低频可以、每帧禁止。要反映到 JSX 的低频状态用 store/useState；高频动画用 ref 直改。</li><li><strong>Q：转速这种每帧读的值放哪？</strong> zustand 存值，useFrame 里 <code>useStore.getState().speed</code> transient 直读——不订阅所以零重渲染。</li><li><strong>Q：R3F 创建的对象能当原生 three 用吗？</strong> 能，挂 <code>ref</code> 拿到的就是货真价实的 <code>THREE.Mesh</code>；<code>useThree()</code> 还能拿到 scene/camera/gl。</li><li><strong>Q：Vue 用户有没有对应方案？</strong> 有，TresJS——同样的声明式理念，换成 Vue 模板语法。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>原生 three 的 <code>scene.add(mesh)</code> 在 R3F 里对应什么写法？JSX 属性又对应什么？</li><li>为什么在 <code>useFrame</code> 里调用 <code>setState</code> 会导致卡顿？正确做法是什么？</li><li><code>&lt;boxGeometry args={[1, 1, 1]} /&gt;</code> 中的 <code>args</code> 起什么作用？如果想给场景加雾，JSX 该怎么写？</li></ol><details><summary>答案</summary><ol><li>把 <code>&lt;mesh&gt;</code> 作为 JSX 子节点写进 <code>&lt;Canvas&gt;</code> 即完成 add（嵌套关系 = 场景图父子关系）；JSX 属性对应实例属性赋值，如 <code>position={[0,1,0]}</code> 等价于 <code>mesh.position.set(0,1,0)</code>，连字符属性可深入嵌套（<code>shadow-mapSize</code>）。</li><li>setState 会触发 React 重渲染，useFrame 里每帧调用等于每秒重渲染 60 次，reconciler 开销直接压垮帧率。正确做法：高频动画用 <code>ref.current</code> 直改 three 对象（不经过 React）；需要状态的用 zustand transient 读取。</li><li><code>args</code> 是构造函数参数数组，等价于 <code>new THREE.BoxGeometry(1, 1, 1)</code>。加雾：<code>&lt;fogExp2 attach=&quot;fog&quot; args={[&#39;#05070c&#39;, 0.022]} /&gt;</code>——雾是 scene 的命名属性，必须显式 <code>attach=&quot;fog&quot;</code>。</li></ol></details>`,22)])])}const g=s(o,[["render",l]]);export{k as __pageData,g as default};
